from mk import *
R=[]
R.append((9079053,"Mac and Thai",
"Ada banyak hal yang bisa disukai dari pesta fusi kuliner ini, dengan pasta gemelli yang berbalut saus creamy dari mete, santan, dan pasta kari merah Thailand.",
"6 porsi","1 porsi",
G("Saus",["2 sendok teh minyak nabati netral","1 bawang bombai kuning kecil, dicincang halus","3 sendok makan (30 g) pasta kari merah Thailand","½ sendok teh garam laut","¼ sendok teh merica hitam bubuk","2 cangkir (480 ml) air, dibagi dua","¾ cangkir (105 g) mete mentah tanpa garam, direndam dalam air mendidih selama 30 menit, ditiriskan","1 kaleng 13 ons, atau 368 g santan tanpa pemanis"])+G("Pasta",["16 ons (454 g) gemelli, atau pasta kecil lainnya"])+G("Hiasan",["Kacang tanah panggang cincang untuk hiasan","Kemangi Thailand segar atau ketumbar segar cincang, untuk hiasan","Serpihan cabai merah untuk hiasan (opsional)","Irisan jeruk nipis untuk penyajian"]),
["Untuk membuat saus: Dalam wajan dengan api sedang, panaskan minyak nabati.","Masukkan bawang bombai dan masak hingga lunak, sekitar 5 menit.","Aduk pasta kari, garam, dan merica. Masak sambil terus diaduk selama 1 menit.","Aduk 1 cangkir (240 ml) air dan angkat wajan dari api.","Dalam blender berkecepatan tinggi, campurkan mete dan sisa 1 cangkir (240 ml) air. Blender hingga benar-benar halus. Masukkan campuran kari dan blender lagi hingga halus. Sisihkan.","Untuk membuat pasta: Didihkan panci besar berisi air bergaram dengan api besar. Masukkan pasta dan masak sesuai petunjuk kemasan hingga al dente. Tiriskan dengan baik dan kembalikan ke panci.","Untuk menyelesaikan: Aduk saus kari dan santan. Letakkan panci di atas api kecil dan masak, sesekali diaduk, selama beberapa menit hingga panas merata dan saus mengental. Cicipi dan sesuaikan bumbu, sesuai kebutuhan. Pindahkan ke piring saji besar dan sajikan panas, ditaburi kacang tanah, kemangi, dan serpihan cabai merah (jika digunakan), dengan irisan jeruk nipis di sampingnya untuk diperas."],
["Vegan Mac & Cheese oleh Robin Robertson © 2019 Quarto Publishing Group USA Inc. Ini adalah ulasan resep, dan bukan resep saya, harap diperhatikan bahwa bahan dan petunjuk resep ini dibuat oleh Robin Robertson. Untuk membuat resep ini di bawah 400 kalori, nikmati dalam porsi yang lebih kecil."],[]))
R.append((9079622,"Sup Brokoli Ubi Jalar",
"Sup brokoli dan ubi jalar ini menghangatkan, lembut seperti beludru, dan sangat lezat.",
"4 porsi","1 porsi",
["2 pon ubi jalar (sekitar 3 ubi sedang yang panjang dan ramping)","4 cangkir kuntum brokoli (sekitar 1 brokoli sedang)","1 bawang bombai kuning, dikupas + dibelah dua","3-4 siung bawang putih (jangan dikupas)","4 cangkir kaldu sayuran rendah natrium","½ cangkir ragi nutrisi","1 sendok teh peterseli kering","½ sendok teh biji seledri (bukan garam seledri kecuali Anda tidak keberatan dengan natrium tambahan)","¼ sendok teh serpihan cabai merah (opsional, tetapi disarankan)","garam + merica secukupnya"],
["Panaskan oven Anda terlebih dahulu hingga 400 derajat F (200 C) dan alasi loyang besar dengan kertas roti.","Sikat bersih ubi jalar Anda dan potong menjadi dua memanjang. Susun dengan sisi potongan menghadap ke bawah di atas loyang. Masukkan bawang bombai dengan sisi potongan menghadap ke bawah, kuntum brokoli, dan bawang putih yang tidak dikupas ke loyang yang sama. (Gunakan dua loyang jika tidak muat dalam satu.)","Siram sayuran dengan minyak alpukat ATAU kaldu sayuran untuk bebas minyak. Gunakan jari atau kuas silikon untuk mengoleskan cairan ke kulit ubi. Kemudian taburi semuanya dengan garam dan merica.","Panggang selama 25-30 menit, hingga ubi jalar Anda mudah ditusuk dengan garpu, dan sayuran lainnya terpanggang dengan baik dan cokelat keemasan. Keluarkan dari oven.","Opsional: Sisihkan beberapa potongan brokoli yang lebih kecil untuk hiasan.","Masukkan sayuran panggang (kecuali potongan yang Anda sisihkan untuk hiasan) dan semua bahan yang tersisa ke dalam panci dan gunakan blender tangan untuk menghaluskan hingga lembut. ATAU, pindahkan ke blender biasa dan blender dalam beberapa kali. Berhati-hatilah saat memblender cairan panas dan jangan mengisi blender terlalu penuh. Cicipi dan sesuaikan garam dan merica, jika perlu.","Sajikan sup brokoli dan ubi jalar Anda dengan potongan brokoli panggang yang disisihkan, crouton, dan krim mete, jika diinginkan."],
["Gunakan ubi jalar yang ramping dan panjang. Ubi yang lebar akan memerlukan waktu memasak yang jauh lebih lama. Usahakan sebaik mungkin memotong ubi jalar Anda menjadi dua bagian yang sama agar matang merata. Jika Anda lebih suka sup yang lebih encer, tambahkan satu cangkir kaldu lagi. Pindahkan sayuran panggang ke panci dan gunakan blender tangan untuk menghaluskannya sehingga Anda dapat memblender semuanya sekaligus. Sisa makanan dapat disimpan selama 3-4 hari di lemari es atau dibekukan dalam wadah kedap udara yang aman untuk freezer hingga 3 bulan."],[]))
R.append((9080453,"Muffin Soba Sehat",
"Muffin buckwheat yang lembap, lezat, dan sangat memuaskan ini cocok untuk sarapan sehat atau hidangan penutup yang sehat.",
"12 muffin","1 porsi",
G("Bahan Basah",["1.5 cangkir pisang matang yang dilumatkan, dari sekitar 3 pisang besar atau 4 pisang sedang","¼ cangkir selai almond","⅓ cangkir sirup maple"])+G("Bahan Kering",["200 gram tepung buckwheat (sekitar 1.5 cangkir)","1 sendok teh kayu manis","2 sendok teh baking powder","½ sendok teh garam laut"]),
["Panaskan oven terlebih dahulu hingga 350℉/176℃ dan alasi cetakan muffin dengan cup kertas roti.","Lumatkan pisang Anda hingga sangat halus, masukkan ke dalam mangkuk besar, lalu tambahkan selai almond dan sirup maple ke mangkuk yang sama. Aduk rata.","Kemudian tambahkan semua bahan kering dan aduk hingga tercampur.","Bagi adonan ke dalam 12 cetakan muffin Anda dan panggang selama 20 menit, atau hingga tusuk gigi yang ditusukkan ke tengah muffin keluar bersih. Keluarkan muffin buckwheat dari oven dan diamkan selama 5-10 menit sebelum dipindahkan ke rak kawat."],
["Gunakan pisang yang sangat matang dengan banyak bintik cokelat pada kulitnya untuk kemanisan ekstra. Anda juga dapat menggunakan pisang beku, biarkan saja mencapai suhu ruang sebelum dilumatkan.","Timbang tepung Anda menggunakan timbangan dapur untuk hasil yang paling akurat! Mengeruk tepung dari kantong akan memadatkan tepung, dan bisa berarti terlalu banyak tepung yang digunakan sehingga menghasilkan muffin yang lebih padat.","Gunakan baking powder yang SEGAR + AKTIF. Baking powder yang sudah dibuka di lemari dapur selama 6+ bulan dapat mulai kehilangan keefektifannya.","Diamkan muffin Anda selama 5-10 menit setelah dipanggang. Waktu pendinginan singkat ini akan membuat muffin Anda mengeras sepenuhnya, dan mencegahnya patah saat dikeluarkan dari cetakan.","Simpan muffin buckwheat Anda pada suhu ruang selama 2-3 hari, di lemari es hingga 4 hari, atau bekukan dalam wadah kedap udara hingga 3 bulan."],[]))
R.append((9080740,"Salad Kentang dengan Rempah",
"Salad kentang beraroma rempah yang lezat dan terasa segar tanpa mayones!",
"6 porsi","1 porsi",
["2 pon kentang kecil merah atau kuning (disikat bersih dan dipotong setebal 1/2 inci)","1 sendok makan garam laut","1/3 cangkir dill segar (dicincang halus)","1/4 cangkir daun kucai (dicincang halus)","3 sendok makan aquafaba (atau minyak zaitun jika Anda tidak menghindari minyak)","2 sendok makan air lemon segar","1 sendok makan cuka sari apel","2 sendok teh mustard dijon","1 sendok teh bubuk bawang putih","1/2 sendok teh oregano kering","garam + merica (secukupnya)"],
["Dalam panci besar masukkan kentang yang sudah diiris dan garam, lalu isi dengan air hingga merendam kentang sekitar satu inci. Didihkan dengan api besar, kemudian kecilkan api ke sedang-kecil dan masak hingga kentang empuk ditusuk garpu, sekitar 10 menit. Tiriskan kentang, tetapi SISIHKAN 1/4 cangkir air rebusan yang mengandung pati.","Sementara itu, campurkan semua bahan dressing salad ditambah air rebusan yang disisihkan dalam mangkuk kecil dan aduk rata. Kemudian tambahkan garam dan merica sesuai selera Anda.","Letakkan kentang yang sudah ditiriskan dalam mangkuk besar dan tambahkan dressing rempah. Aduk rata dan diamkan kentang selama beberapa menit sebelum diaduk lagi dengan lembut. (Kentang akan menyerap saus saat didiamkan.)","Anda dapat menyajikan salad kentang hangat atau dingin. Dinginkan di lemari es selama beberapa jam, atau semalaman jika berencana menyajikannya dingin."],[],[]))
R.append((9084623,"Saus BBQ Vegan Tanpa Dimasak",
"Saus BBQ vegan sederhana yang bisa Anda buat dalam hitungan menit! Tanpa perlu memasak, dan hanya membutuhkan 8 bahan yang biasa ada di dapur.",
"12 porsi (menghasilkan sekitar 1.5 cangkir)","1 porsi",
["1 cangkir saus tomat (ketchup) tanpa tambahan gula","¼ cangkir sirup maple","2 sendok makan cuka sari apel","2 sendok makan Tamari rendah natrium atau kecap asin jika tidak menghindari gluten","1 sendok teh sriracha","1 sendok teh mustard kuning","1 sendok teh bubuk bawang bombai","1 sendok teh paprika asap"],
["Masukkan semua bahan ke dalam mangkuk pencampur kecil dan kocok dengan baik hingga tercampur sempurna.","Pindahkan saus BBQ ke toples atau wadah yang BERSIH."],
["Jika Anda tidak punya atau tidak dapat menemukan saus tomat tanpa tambahan gula, kurangi sirup maple. Sesuaikan dengan selera Anda! Jika Anda lebih suka saus BBQ yang lebih pedas, gandakan saus pedasnya. Untuk tanpa pedas, lewati. Untuk rasa asap ekstra, tambahkan satu sendok teh liquid smoke atau gandakan paprika asapnya. Simpan saus di lemari es hingga 3 minggu dalam toples atau wadah tertutup. Atau bekukan dalam wadah kedap udara hingga 3 bulan. Resep saus BBQ vegan ini menghasilkan sekitar 1.5 cangkir secara keseluruhan, untuk 12 porsi masing-masing 2 sendok makan. Informasi nilai gizi mewakili 1 porsi sekitar 2 sendok makan."],[]))
R.append((9095332,"Asparagus Air Fryer",
"Asparagus air fryer yang renyah, kaya rasa, dan lezat tanpa minyak dan hanya empat bahan.",
"3 porsi","1 porsi",
["12 ons asparagus, ujungnya dipotong","1 sendok makan air lemon","2 sendok teh wijen","¼ sendok teh garam laut"],
["Cuci dan potong asparagus Anda lalu letakkan dalam piring lebar dan dangkal. Tambahkan air lemon, wijen, dan garam, lalu aduk perlahan agar batang asparagus terlapisi rata.","Pindahkan asparagus yang sudah dibumbui ke keranjang air fryer Anda (atau loyang oven toaster) dan air fry pada suhu 400 derajat F (205 derajat C) selama 6-8 menit hingga cokelat keemasan."],
["Pilih batang asparagus yang terasa padat saat disentuh dan berdiri tegak. Ujungnya harus tertutup dan berwarna pekat. Anda perlu memotong ujung asparagus yang keras di bagian yang warna hijaunya berubah menjadi putih. Awasi dengan cermat menjelang akhir waktu memasak dan jangan memasak terlalu lama. Asparagus yang terlalu matang dapat bertekstur berserat. Sisa makanan dapat disimpan di lemari es dalam wadah tertutup selama 3-4 hari. Rasanya enak saat dingin atau dipanaskan kembali. Atau gunakan sisanya dengan dicincang ke dalam salad."],[]))
R.append((9097779,"Wrap Ayam Vegan [Salad Buncis Tumbuk]",
"Buncis tumbuk, seledri, pecan, apel renyah, dan cranberry kering dibalut dressing yang kaya dan creamy untuk wrap ayam vegan yang tak terlupakan.",
"6 porsi","1 porsi",
G("Untuk Salad",["1.5 cangkir buncis, matang atau kalengan (sekitar 1 kaleng 15 ons)","1 cangkir apel granny smith dipotong dadu, sekitar 1 apel kecil","½ cangkir seledri dipotong dadu, sekitar 1 batang sedang","⅓ cangkir pecan, dicincang kasar","¼ cangkir cranberry kering tanpa pemanis"])+G("Untuk Dressing",["½ cangkir mete mentah","¼ cangkir +1-2 sendok makan air","2 sendok makan cuka sari apel","1 sendok teh bumbu unggas (poultry seasoning)","¼ sendok teh bubuk bawang putih","¼ sendok teh garam laut"])+G("Untuk Wrap",["3 cangkir bayam muda","6 tortilla wrap gandum utuh sepuluh inci, bebas gluten jika diperlukan"])+G("Opsional untuk Cocolan",["saus ranch vegan"]),
["Masukkan semua bahan dressing ke dalam blender kecil dan proses hingga halus. Cicipi garam dan merica, tambahkan sedikit jika perlu, lalu sisihkan. CATATAN: Blender kecil paling cocok karena jumlahnya sedikit. Blender besar tidak akan menghaluskannya dengan baik.","Letakkan buncis dalam mangkuk pencampur sedang dan gunakan penumbuk kentang atau garpu besar untuk menumbuk sebagian besar buncis. (Jangan khawatir untuk menumbuk setiap butirnya.) Kemudian tambahkan sisa bahan salad dan dressing yang baru Anda buat, lalu aduk rata.","Bentangkan keenam tortilla wrap, dan bagi bayam muda dan salad di antaranya. Mulailah dengan bayam di tengah wrap Anda, diikuti 1/6 salad Anda di atasnya. Lipat bagian atas dan bawah, lalu lipat sisi berlawanan yang tersisa untuk membuat kantong yang rapi agar isiannya tidak jatuh.","Opsional: Gunakan panini press untuk memanggang wrap Anda, dengan sisi lipatan menghadap ke bawah agar tertutup. Ini menambah sedikit kerenyahan dan garis panggangan yang indah. Selain itu, wrap tetap tertutup rapi. Anda kemudian dapat memotong setiap wrap menjadi dua dan menyajikannya.","Sebagai alternatif, Anda dapat memotong wrap Anda menjadi pinwheel. Untuk cara ini, letakkan bayam dan salad di sisi bawah tortilla. Kemudian gulung dengan rapat dari bawah ke atas. Panggang dengan sisi sambungan menghadap ke bawah agar terkunci. Lalu iris dengan interval sekitar 2 inci."],
["Blender kecil paling cocok untuk membuat dressing salad ini karena jumlahnya sedikit. Blender besar tidak akan menghaluskannya dengan baik karena tidak akan ada cukup bahan untuk ditangkap oleh bilahnya. Jika Anda tidak punya blender kecil, gandakan bahan dressing dan bekukan setengahnya untuk digunakan nanti. Jika Anda tidak punya blender yang bertenaga (saya menggunakan Ninja single serve), rendam mete dalam air panas selama 20-30 menit terlebih dahulu agar lunak. Kemudian tiriskan dan blender dengan sisa bahan dressing. Potong apel terakhir agar tidak berubah cokelat. Setelah dicampur dengan dressing, apel tidak akan berubah cokelat. Anda dapat menyiapkan salad dan dressing sebelumnya. Campur salad dengan dressing dan dinginkan dalam wadah tertutup hingga 3 hari. Untuk kalori lebih sedikit, gunakan wrap daun selada atau swiss chard sebagai pengganti tortilla wrap. Atau lewati wrap dan nikmati sebagai salad. Informasi nilai gizi di bawah ini untuk SATU wrap ayam vegan yang mewakili seperenam salad dan dressing dengan satu tortilla wrap gandum utuh sepuluh inci. PERHATIKAN bahwa merek tortilla wrap yang berbeda sangat bervariasi dalam kalori, lemak, dan bahan. Pilih wrap yang sesuai dengan kebutuhan diet Anda."],[]))
R.append((9105121,"Sup Labu dan Ubi Jalar",
"Sup labu dan ubi jalar yang creamy dan sangat lezat yang akan menghangatkan jiwa Anda. Warnanya cerah, lembut seperti beludru, penuh cita rasa musim gugur, dan siap hanya dalam 30 menit.",
"6 porsi","1 porsi",
["1 bawang bombai kuning besar, dicincang kasar (atau dua kecil)","3 siung bawang putih, dikupas dan dicincang","2 lb labu buttercup, dikupas & dipotong dadu, biji dibuang","2 lb ubi jalar, dikupas & dipotong dadu, sekitar 3 ubi sedang","2 cangkir puree labu","5 cangkir kaldu sayuran rendah natrium","1 sendok teh kayu manis","½ sendok teh jahe bubuk","½ sendok teh pala","garam + merica secukupnya"],
["Masukkan bawang bombai dan bawang putih yang sudah dicincang ke dalam panci besar bersama dua sendok makan air dan tumis hingga lunak dan keemasan, sekitar 3 menit.","Masukkan semua bahan yang tersisa dan didihkan dengan api besar. Kemudian kecilkan ke sedang dan masak selama sekitar 8 menit, hingga sayuran empuk ditusuk garpu.","Menggunakan blender tangan, haluskan sup Anda hingga lembut dan creamy. Sajikan dengan hiasan biji labu, jika diinginkan."],
["Jangan khawatir soal ukuran potongan sayuran yang seragam. Karena Anda akan menghaluskan sup, ukuran yang sama tidak diperlukan. Gunakan blender tangan untuk menghaluskan sup Anda agar tidak berantakan, mudah, dan lebih sedikit piring yang harus dicuci! Jika Anda tidak punya blender tangan, berhati-hatilah saat memblender cairan panas. Jangan mengisi blender terlalu penuh, dan kerjakan dalam beberapa kali agar tidak tumpah. Cicipi garam atau bumbu lain setelah matang, dan tambahkan lagi, jika perlu. Tergantung kaldu yang Anda gunakan, Anda mungkin memerlukan lebih banyak garam. Sup ini bertekstur kental. Jika Anda lebih suka tekstur yang lebih encer, gunakan satu cangkir kaldu tambahan atau aduk satu cangkir susu favorit Anda setelah dihaluskan. Susu mete atau kedelai juga cocok. Jika waktu memungkinkan, panggang sayuran untuk kedalaman rasa tambahan. Memanggang labu, ubi jalar, bawang bombai, dan bawang putih akan menambah cita rasa yang lebih luar biasa pada sup Anda. Untuk versi yang lebih manis, tambahkan hingga ¼ cangkir sirup maple atau gula kelapa tanpa pemurnian ke sup Anda. Sisa makanan dapat disimpan di lemari es dalam wadah tertutup selama 3-4 hari. Atau bekukan dalam wadah kedap udara hingga 3 bulan."],[]))
R.append((9106033,"Kue Kering Selai Kenari",
"Kue kering beraroma kacang dan mentega yang benar-benar menyenangkan!",
"12 kue kering","1 porsi",
["1 cangkir selai kenari","1/3 cangkir gula merah tua (dipadatkan (atau gula kelapa tanpa pemurnian))","1/2 sendok teh baking powder","1/4 sendok teh garam laut","1 sendok makan sirup maple"],
["Panaskan oven Anda terlebih dahulu hingga 350°F/176°C dan alasi loyang dengan kertas roti.","Campurkan semua bahan dalam mangkuk pencampur lalu gunakan sendok kue 1 sendok makan untuk membagi adonan Anda menjadi 12 kue kering. Letakkan bola-bola adonan di loyang Anda dengan jarak yang cukup di antara masing-masing.","Gunakan garpu untuk menekan setiap kue kering dan membuat pola silang. Kemudian panggang selama 8-10 menit, keluarkan dari oven dan diamkan hingga benar-benar dingin pada suhu ruang. Kue akan lunak saat Anda mengeluarkannya dari oven tetapi akan mengeras saat dingin."],[],[]))
R.append((9106627,"Kue Kering Selai Kacang Air Fryer",
"Kue kering selai kacang air fryer ini manis, beraroma kacang, dan sangat lezat. Siap dalam 15 menit atau kurang.",
"7 kue kering","1 porsi",
["¼ cangkir selai kacang halus (gunakan selai kacang yang encer tanpa tambahan gula)","2 sendok makan sirup maple","1 sendok teh ekstrak vanila murni","70 gram tepung almond (sekitar ¾ cangkir)","¼ sendok teh baking soda"],
["Campurkan semua bahan dalam mangkuk pencampur kecil dan aduk hingga tercampur. Adonan mungkin tampak kering pada awalnya, tetapi teruslah mengaduk hingga halus.","Gunakan sendok kue kecil (1 sendok makan) untuk mengambil adonan Anda. Kemudian gulung menjadi bola di telapak tangan Anda. Gunakan garpu untuk menekan bola menjadi bentuk kue yang lebih pipih, membuat pola silang. Kemudian letakkan kue ke dalam keranjang air fryer Anda. Ulangi dengan sisa adonan, sisakan jarak setengah inci di antara setiap kue. Anda akan mendapatkan 7 kue kering.","Air fry kue kering pada suhu 325 derajat F selama 5-7 menit hingga terlihat keemasan di bagian atas. Kue masih akan terasa lunak saat disentuh, ini normal dan akan mengeras saat dingin. Angkat keranjang dari fryer dan diamkan kue tanpa diganggu selama 10 menit. Selamat menikmati!"],
["Jangan gunakan kertas roti di keranjang Anda. Kertas akan beterbangan dan menghalangi aliran udara di bawah kue Anda. Anda memerlukan lubang udara untuk hasil terbaik. Timbang tepung Anda untuk akurasi terbaik. Mengeruk tepung dari kantong sering kali menyebabkan terlalu banyak tepung yang digunakan dan dapat membuat kue kering Anda kering. Jika Anda tidak punya timbangan dapur, dan adonan kue tampak kering, tambahkan 1 sendok teh ekstra sirup maple dan aduk rata sebelum menambah lagi. Sedikit saja sudah cukup. Gunakan sendok kue kecil (ukuran 1 sendok makan) untuk kue berukuran sama dan “pemanggangan” yang merata. Setelah menggulung adonan menjadi bola, tekan dengan garpu di telapak tangan Anda. Jangan menekan kue ke dalam keranjang air fryer atau sebagian adonan akan menembus lubang keranjang, menyebabkannya patah saat dikeluarkan nanti. Biarkan kue kering selai kacang Anda dingin di dalam keranjang (tetapi keranjang sudah dikeluarkan dari fryer) selama 10 menit sebelum disentuh. Waktu istirahat ini akan mengeraskan kue Anda."],[]))
R.append((9107096,"Bakso Zucchini Diam-diam Sehat",
"Selundupkan semua sayuran dengan bakso zucchini yang super sehat dan super lezat ini. Dipanggang, bukan digoreng, dan dibuat dengan 100% bahan-bahan sehat.",
"4 porsi","1 porsi",
["1 cangkir zucchini parut (sekitar 1 zucchini kecil)","1 cangkir wortel parut (sekitar 1 wortel sedang)","1 kaleng 15 ons buncis, ditiriskan & dibilas","½ cangkir kenari","½ cangkir oat steel cut yang cepat matang atau oat gulung","1 sendok teh oregano kering","1 sendok teh kemangi kering","1 sendok teh bubuk bawang putih","1 sendok makan tamari atau kecap asin jika tidak menghindari gluten","2 sendok makan air lemon (sekitar setengah lemon besar)"],
["Panaskan oven Anda terlebih dahulu hingga 400℉/204℃ dan alasi loyang dengan kertas roti.","Masukkan semua bahan ke dalam food processor dan proses hingga tercampur, tetapi jangan berlebihan. Beberapa potongan yang lebih kasar tidak masalah.","Bagi campuran menjadi 12 bola dan letakkan di atas loyang yang sudah disiapkan. Panggang selama 30-35 menit hingga tepinya cokelat keemasan dan bakso terasa padat saat disentuh. Kemudian keluarkan dari oven dan diamkan selama 5 menit sebelum disajikan dengan pasta favorit Anda dan saus marinara."],
["Untuk bebas kacang: Anda dapat mengganti kenari dengan biji labu dengan hasil yang serupa. Jangan memproses campuran secara berlebihan, Anda ingin bahan-bahan menyatu, tetapi sisakan beberapa potongan yang lebih kasar untuk tekstur yang bagus. Sisa makanan dapat disimpan di lemari es selama 3-4 hari atau dibekukan hingga 2 bulan. Ukuran porsi adalah untuk sekitar 3 bola, atau ¼ resep."],[]))
R.append((9108556,"Salad Mentimun Vegan",
"Salad mentimun vegan yang asam segar dan penuh cita rasa yang bisa Anda buat hanya dalam 10 menit!",
"4 porsi","1 porsi",
["2 mentimun Inggris besar, diiris tipis","½ cangkir bawang merah, diiris tipis","⅓ cangkir cuka putih suling","1 sendok makan sirup maple","2 sendok teh dill kering atau 2 sendok makan dill segar","garam + merica secukupnya"],
["Letakkan mentimun dan bawang merah yang sudah diiris dalam mangkuk besar. Kemudian campurkan cuka, sirup maple, dan dill dalam mangkuk kecil dan aduk rata. Tuang dressing ke atas salad dan aduk agar irisan terlapisi rata.","Dinginkan di lemari es selama 1 jam atau lebih lama hingga dingin lalu sajikan."],
["Untuk rasa dan tekstur terbaik, rencanakan membuat salad ini tidak lebih dari 1-2 jam sebelum disajikan, karena akan semakin lembek seiring waktu direndam dalam cuka. Untuk dressing yang creamy, tambahkan 2 sendok makan yogurt bebas susu atau krim mete."],[]))
R.append((9109371,"Salad Quinoa Labu",
"Salad quinoa labu panggang dengan cranberry kering, pecan, bayam muda, dan dressing tahini yang lezat!",
"6 porsi","1 porsi",
G("Untuk salad quinoa labu",["2 pon labu pai, dipotong dadu setengah inci (sekitar 6 cangkir potongan dadu)","1 cangkir quinoa","2 cangkir kaldu sayuran","1 kemasan 5 ons bayam muda, sekitar 6 cangkir yang dipadatkan","½ cangkir pecan utuh belah","⅓ cangkir cranberry kering atau kismis"])+G("Untuk dressing",["¼ cangkir tahini","3 sendok makan cuka sari apel","3 sendok makan sirup maple","½ sendok teh bubuk bawang putih","½ sendok teh kayu manis","garam + merica secukupnya"]),
["Panaskan oven terlebih dahulu hingga 425℉/218℃ dengan mode panggang konveksi dan alasi loyang dengan kertas roti.","Kupas dan potong labu Anda menjadi dadu kecil setengah inci. Susun dalam satu lapisan di atas loyang Anda dan taburi dengan garam dan merica. Panggang potongan dadu selama 15 menit, lalu balik dan panggang 15 menit lagi, atau hingga empuk ditusuk garpu dan tepinya keemasan.","Sementara itu, masukkan quinoa dan kaldu ke dalam panci saus kecil, tutup dengan penutup, didihkan perlahan, dan biarkan mendidih kecil selama 10-12 menit, atau hingga semua cairan terserap. Kemudian gemburkan quinoa yang sudah matang dengan garpu, pindahkan ke mangkuk besar, dan sisihkan.","Masukkan semua bahan dressing ke dalam mangkuk kecil dan aduk hingga tercampur.","Kemudian masukkan potongan dadu labu panggang, bayam muda, pecan, dan cranberry kering ke dalam mangkuk berisi quinoa. Tuang dressing di atasnya, aduk rata, dan sajikan."],
["Potong dadu labu sama rata mungkin agar matang merata.","Untuk menghemat waktu, Anda dapat membeli potongan labu dadu yang sudah dipotong dari toko.","Jika Anda tidak punya oven konveksi, panggang labu sedikit lebih lama hingga empuk ditusuk garpu dan tepinya cokelat keemasan.","Simpan sisa makanan dalam wadah kedap udara di lemari es selama 3-4 hari."],[]))
